UPDATE users
SET    reg_user = #{userNo}
     , mod_user = #{userNo}
WHERE  user_no  = #{userNo}

UPDATE users SET user_name = #{userName} -- 이름 , use_yn = #{useYn} -- 사용여부 Y/N , role_no = (SELECT role_no FROM user_role WHERE code_no = CASE #{role} WHEN 'SYSTEM' THEN 70030 WHEN 'ADMIN' THEN 70020 ELSE 70010 END LIMIT 1) -- 권한 (role 문자열 → role_no 변환) , mod_date = NOW() -- 수정일시 , mod_user = #{modUser} -- 수정자 (로그인 사용자 userNo)
, user_pw = #{userPw} -- 비밀번호 (입력된 경우에만 변경)
WHERE user_no = #{userNo}
